:root {
  --cream: #f5ead0;
  --burgundy: #7c1c2e;
  --gold: #c89b3c;
  --dark: #2b1a10;
  --muted: #8a6f55;
  --ivory: #fdf8ef;
  --green-accent: #3a6b4e;
  --black-key: #1e1008;
  --bellow-light: #e8d4a8;
  --bellow-dark: #b8955a;
  --highlight: #f0e4c0;
}

.pass {
  width: 480px;
  background: var(--cream);
  border: 3px solid var(--burgundy);
  border-radius: 10px;
  overflow: hidden;
  font-size: 13px;
  color: var(--dark);
  margin: 0 auto;
}

.pass-header {
  background: var(--burgundy);
  color: var(--cream);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
}

.pass-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  border: 1.5px solid var(--gold);
  padding: 3px 8px;
  border-radius: 3px;
  color: var(--gold);
}

.pass-year {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: 2px;
  color: var(--gold);
}

.pass-body {
  display: flex;
  gap: 0;
}

.pass-left {
  width: 180px;
  flex-shrink: 0;
  background: var(--ivory);
  border-right: 2px dashed var(--gold);
  padding: 14px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.accordion-icon {
  width: 100px;
  display: flex;
  justify-content: center;
}

.accordion-body {
  width: 80px;
  background: var(--burgundy);
  border-radius: 6px;
  padding: 6px 5px 4px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  border: 2px solid var(--dark);
}

.key-row {
  display: flex;
  gap: 3px;
  justify-content: center;
}

.key-row--white .key {
  width: 11px;
  height: 16px;
  background: var(--ivory);
  border-radius: 2px;
  border: 1px solid var(--muted);
}

.key-row--black .key {
  width: 9px;
  height: 11px;
  background: var(--black-key);
  border-radius: 1px;
}

.bellows {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-top: 2px;
}

.bellow {
  height: 6px;
  border-radius: 1px;
  background: repeating-linear-gradient(
    to right,
    var(--bellow-dark) 0px,
    var(--bellow-dark) 4px,
    var(--bellow-light) 4px,
    var(--bellow-light) 8px
  );
  border-top: 1px solid var(--dark);
  border-bottom: 1px solid var(--dark);
}

.pass-event {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  text-align: center;
}

.event-name {
  font-size: 13px;
  font-weight: 800;
  color: var(--burgundy);
  line-height: 1.2;
  font-style: italic;
}

.event-sub {
  font-size: 10px;
  color: var(--muted);
  font-weight: 600;
  letter-spacing: 0.5px;
  text-align: center;
}

.pass-right {
  flex: 1;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px dotted var(--bellow-dark);
  padding-bottom: 5px;
}

.detail-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.detail-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--dark);
}

.detail-value.highlight {
  color: var(--green-accent);
  font-weight: 800;
  font-size: 13px;
  background: var(--highlight);
  padding: 1px 7px;
  border-radius: 4px;
  border: 1px solid var(--gold);
}

.stamp-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 2px;
}

.stamp {
  width: 52px;
  height: 52px;
  border: 3px solid var(--burgundy);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 2px;
  color: var(--burgundy);
  opacity: 0.75;
  transform: rotate(-12deg);
  flex-shrink: 0;
}

.perks {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.perks li {
  font-size: 11px;
  font-weight: 600;
  color: var(--dark);
}

.pass-footer {
  background: var(--dark);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.barcode {
  display: flex;
  align-items: stretch;
  height: 28px;
  gap: 2px;
}

.bar {
  width: 3px;
  background: var(--cream);
  border-radius: 1px;
}

.bar.thin {
  width: 1.5px;
}

.bar.wide {
  width: 5px;
}

.pass-id {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--gold);
  font-style: italic;
}
